WITH parsed AS (SELECT id, currency, tier_prices, discounts, ARRAY_MIN(tier_prices) AS lowest_price, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers WHERE currency IN ('EUR', 'USD', 'THB')) SELECT CASE WHEN lowest_price >= 34 THEN 'LARGE' ELSE 'SMALL' END AS lowest_price_tier, currency, COUNT(DISTINCT id) AS distinct_ids, COUNT(DISTINCT currency) AS distinct_currencies, SORT_ARRAY(COLLECT_SET(currency)) AS currency_list, COUNT(DISTINCT currency) AS distinct_currencies_2, GROUPING_ID() AS grouping_level FROM parsed GROUP BY GROUPING SETS ((CASE WHEN lowest_price >= 34 THEN 'LARGE' ELSE 'SMALL' END, currency), (CASE WHEN lowest_price >= 34 THEN 'LARGE' ELSE 'SMALL' END)) ORDER BY distinct_ids
